import { NextRequest, NextResponse } from "next/server";
import { getPostgresPool } from "@/lib/db";
import sessionCloses from "@/app/data/amd-session-closes.json";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

// AMD V2 chart source: raw daily / 30m; complete session-anchored 1h groups.
// No daily H/L clipping, no synthetic tail. Calendar generated by amd_data.py.
export async function GET(request: NextRequest) {
  const sp = request.nextUrl.searchParams;
  const sym = (sp.get("sym") || "").toUpperCase();
  const tf = sp.get("tf") || "1d", from = sp.get("from"), to = sp.get("to");
  if (!/^[A-Z.\-]{1,12}$/.test(sym) || !["1d", "1h", "30m"].includes(tf) || !from || !to || !/^\d{4}-\d{2}-\d{2}$/.test(from) || !/^\d{4}-\d{2}-\d{2}$/.test(to)) {
    return NextResponse.json({ok:false,error:"Valid symbol, timeframe and date bounds required"},{status:400});
  }
  const source = tf === "1d"
    ? `SELECT (candle_ts AT TIME ZONE 'America/New_York')::date::timestamp AS ts,open_price o,high_price h,low_price l,close_price c
       FROM candles_1d WHERE market='us' AND base_symbol=$1 AND candle_ts >= '2015-06-30'
       UNION ALL SELECT (candle_ts AT TIME ZONE 'America/New_York')::date::timestamp,open_price,high_price,low_price,close_price
       FROM historical_candles_1d WHERE market='us' AND base_symbol=$1 AND base_symbol IN ('SPY','QQQ') AND candle_ts >= '2015-06-30'`
    : `SELECT candle_ts AT TIME ZONE 'America/New_York' AS ts,open_price o,high_price h,low_price l,close_price c
       FROM candles_30m WHERE market='us' AND base_symbol=$1 AND candle_ts >= '2026-01-21'
       UNION ALL SELECT candle_ts AT TIME ZONE 'America/New_York',open_price,high_price,low_price,close_price
       FROM historical_candles_30m WHERE market='us' AND base_symbol=$1 AND candle_ts >= '2015-06-30'
       AND (base_symbol IN ('SPY','QQQ') OR candle_ts < '2026-01-21')`;
  const available = tf === "1d"
    ? `ts::date + ($4::jsonb->>ts::date::text)::time`
    : `least(ts + interval '30 minutes', ts::date + ($4::jsonb->>ts::date::text)::time)`;
  const aggregation = tf === "1h"
    ? `SELECT bucket AS ts,(array_agg(o ORDER BY ts))[1] o,max(h) h,min(l) l,(array_agg(c ORDER BY ts DESC))[1] c
       FROM (SELECT *,ts::date + interval '9 hours 30 minutes' + floor(extract(epoch FROM (ts-(ts::date+interval '9 hours 30 minutes')))/3600)*interval '1 hour' AS bucket FROM continuous) q
       GROUP BY bucket HAVING count(*)=extract(epoch FROM (least(bucket+interval '1 hour',bucket::date+($4::jsonb->>bucket::date::text)::time)-bucket))/1800`
    : `SELECT ts,o,h,l,c FROM continuous`;
  try {
    const {rows} = await getPostgresPool().query(`WITH raw AS (${source}), sane AS (
      SELECT * FROM raw WHERE o>0 AND l>0 AND c>0 AND h>=greatest(o,c,l) AND l<=least(o,c,h)
        AND $4::jsonb ? ts::date::text
        ${tf === "1d" ? "" : "AND ts::time>='09:30' AND ts::time<($4::jsonb->>ts::date::text)::time AND extract(minute FROM ts) IN (0,30) AND extract(second FROM ts)=0"}
        AND (${available}) AT TIME ZONE 'America/New_York' <= now()
    ), unique_bars AS (
      SELECT ts,min(o) o,min(h) h,min(l) l,min(c) c FROM sane GROUP BY ts
      HAVING min(o)=max(o) AND min(h)=max(h) AND min(l)=max(l) AND min(c)=max(c)
    ), jumps AS (SELECT *,abs(c/nullif(lag(c) OVER(ORDER BY ts),0)-1)>.6 AS jumped FROM unique_bars),
    continuous AS (SELECT ts,o,h,l,c FROM (SELECT *,sum(jumped::int) OVER(ORDER BY ts) AS jump_count FROM jumps) j WHERE coalesce(jump_count,0)=0),
    aggregated AS (${aggregation}),
    hourly_jumps AS (SELECT *,abs(c/nullif(lag(c) OVER(ORDER BY ts),0)-1)>.6 AS jumped FROM aggregated),
    final AS (SELECT *,sum(jumped::int) OVER(ORDER BY ts) AS jump_count FROM hourly_jumps)
    SELECT to_char(ts,${tf === "1d" ? "'YYYY-MM-DD'" : "'YYYY-MM-DD HH24:MI'"}) AS key,
      o::float AS open,h::float AS high,l::float AS low,c::float AS close FROM final
      WHERE coalesce(jump_count,0)=0 AND ts::date BETWEEN $2::date AND $3::date ORDER BY ts`,[sym,from,to,JSON.stringify(sessionCloses)]);
    return NextResponse.json({ok:true,sym,tf,source:"amd_raw_completed_v2",candles:rows});
  } catch (error) {
    return NextResponse.json({ok:false,error:error instanceof Error ? error.message : String(error)},{status:500});
  }
}
